const here = position();
if (inventory_count('cobblestone') < 3) {
  const took = await take_from_depot('cobblestone');
  if (!took.ok) {
    return { done: false, detail: took.detail };
  }
}
for (let i = 1; i <= 3; i++) {
  const put = await place('cobblestone', here.x, here.y + i, here.z);
  if (!put.ok) {
    return { done: false, detail: put.detail };
  }
}
return { done: true, detail: 'raised a three block pillar' };
